export function computeInvoice(input) {
  const lines = input == null ? undefined : input.lines;

  if (!Array.isArray(lines)) {
    throw new RangeError("lines must be an array");
  }

  const rawDiscount = input.discountKobo;
  const requestedDiscount =
    rawDiscount === undefined ? 0 : rawDiscount;

  if (
    !Number.isInteger(requestedDiscount) ||
    requestedDiscount < 0
  ) {
    throw new RangeError("discountKobo must be a non-negative integer");
  }

  const lineData = new Array(lines.length);
  let subtotal = 0n;

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const unitPriceKobo =
      line == null ? undefined : line.unitPriceKobo;
    const qty = line == null ? undefined : line.qty;

    if (
      !Number.isInteger(unitPriceKobo) ||
      unitPriceKobo < 0
    ) {
      throw new RangeError(
        "unitPriceKobo must be a non-negative integer"
      );
    }

    if (!Number.isInteger(qty) || qty < 1) {
      throw new RangeError("qty must be a positive integer");
    }

    const lineSubtotal =
      BigInt(unitPriceKobo) * BigInt(qty);

    subtotal += lineSubtotal;
    lineData[index] = {
      sku: line.sku,
      vatExempt: line.vatExempt,
      subtotal: lineSubtotal,
    };
  }

  const requestedDiscountBigInt = BigInt(requestedDiscount);
  const appliedDiscount =
    requestedDiscountBigInt < subtotal
      ? requestedDiscountBigInt
      : subtotal;

  const allocations = new Array(lines.length).fill(0n);

  if (subtotal > 0n && appliedDiscount > 0n) {
    const remainders = new Array(lines.length);
    let allocated = 0n;

    for (let index = 0; index < lineData.length; index += 1) {
      const numerator =
        appliedDiscount * lineData[index].subtotal;
      const allocation = numerator / subtotal;

      allocations[index] = allocation;
      allocated += allocation;
      remainders[index] = {
        index,
        remainder: numerator % subtotal,
      };
    }

    remainders.sort((a, b) => {
      if (a.remainder > b.remainder) return -1;
      if (a.remainder < b.remainder) return 1;
      return a.index - b.index;
    });

    let leftover = appliedDiscount - allocated;

    for (let index = 0; leftover > 0n; index += 1) {
      allocations[remainders[index].index] += 1n;
      leftover -= 1n;
    }
  }

  let vatTotal = 0n;

  const resultLines = lineData.map((line, index) => {
    const lineDiscount = allocations[index];
    const net = line.subtotal - lineDiscount;
    const vat =
      line.vatExempt === false
        ? (net * 3n + 20n) / 40n
        : 0n;

    vatTotal += vat;

    return {
      sku: line.sku,
      subtotalKobo: Number(line.subtotal),
      discountKobo: Number(lineDiscount),
      netKobo: Number(net),
      vatKobo: Number(vat),
    };
  });

  return {
    subtotalKobo: Number(subtotal),
    discountKobo: Number(appliedDiscount),
    vatKobo: Number(vatTotal),
    totalKobo: Number(subtotal - appliedDiscount + vatTotal),
    lines: resultLines,
  };
}
